```javascript
/**
 * @param {number} millis
 * @return {Promise}
 */
async function sleep(millis) {
    // The executor schedules resolve() to run after `millis` ms; the event loop is never blocked.
    return new Promise(resolve => setTimeout(resolve, millis));
}

/**
 * let t = Date.now()
 * sleep(100).then(() => console.log(Date.now() - t)) // 100
 */
